const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const windowMs = 24 * 60 * 60 * 1000; // 24h rolling window
const maxPerWindow = 20; // adjust to match the actual Gemini free-tier daily quota

if (!staticData.alertTimestamps) staticData.alertTimestamps = [];
staticData.alertTimestamps = staticData.alertTimestamps.filter((t) => now - t < windowMs);

const withinLimit = staticData.alertTimestamps.length < maxPerWindow;
if (withinLimit) staticData.alertTimestamps.push(now);

const item = $input.first().json;
return [{
  json: {
    ...item,
    _rateLimit: {
      withinLimit,
      countInWindow: staticData.alertTimestamps.length,
      maxPerWindow,
    },
  },
}];
